"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["73288"],{8969(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formulario_processo.fase_fora_do_cronograma","status":422,"titulo":"A fase do formul\xe1rio n\xe3o est\xe1 no cronograma do processo"},"descricao":{"codigo":"uniplus.selecao.formulario_processo.fase_fora_do_cronograma","requisitos":["UNI-REQ-0144"],"oQueAconteceu":["O formul\xe1rio do processo \xe9 ligado a uma fase do cronograma e abre e fecha com o\\nprazo dela; s\xf3 \xe9 publicado ligado a uma fase que existe no cronograma\\n(UNI-REQ-0144). A fase indicada no formul\xe1rio n\xe3o faz parte do cronograma do\\nprocesso. H\xe1 duas ocasi\xf5es:","- **Grava\xe7\xe3o do formul\xe1rio** (`PUT .../formularios/{finalidade}` com `faseId`): o\\n  identificador de fase informado n\xe3o corresponde a nenhuma fase do cronograma\\n  atual. A recusa vem em `faseId` e soma-se, no array `errors[]`, \xe0s recusas das\\n  etapas do mesmo formul\xe1rio. Nada \xe9 gravado.\\n- **Publica\xe7\xe3o e retifica\xe7\xe3o em ato \xfanico**: a\\n  fase gravada no formul\xe1rio n\xe3o \xe9 encontrada no cronograma no momento de\\n  congelar a configura\xe7\xe3o. Esses dois caminhos conferem a prontid\xe3o na mesma\\n  ordem e devolvem a primeira pend\xeancia; as pend\xeancias do formul\xe1rio v\xeam depois\\n  das da inscri\xe7\xe3o, dos dados b\xe1sicos e da edi\xe7\xe3o do ENEM.","A redefini\xe7\xe3o do cronograma que retirasse uma fase em que um formul\xe1rio \xe9\\nrespondido \xe9 recusada, e a mensagem pede a troca da fase do formul\xe1rio antes\\n([`fase_referenciada_por_formulario`](/erros/uniplus.selecao.processo_seletivo.fase_referenciada_por_formulario)).\\nPor isso, a confer\xeancia da prontid\xe3o n\xe3o deve encontrar a fase fora do cronograma\\nquando a configura\xe7\xe3o foi gravada pelas opera\xe7\xf5es normais; n\xe3o foi encontrado,\\nno c\xf3digo, caminho de edi\xe7\xe3o que a produza."],"comoResolver":["Na grava\xe7\xe3o, escolha para o formul\xe1rio uma fase que consta do cronograma do\\nprocesso; se a fase certa ainda n\xe3o foi inclu\xedda, defina o cronograma antes\\n(defini\xe7\xe3o do cronograma de fases) e depois grave o formul\xe1rio. Na publica\xe7\xe3o,\\nregrave o formul\xe1rio com uma fase do cronograma atual e repita a opera\xe7\xe3o. Na\\nretifica\xe7\xe3o em ato \xfanico, o pedido n\xe3o traz o formul\xe1rio, e a recusa indica que\\na configura\xe7\xe3o publicada divergiu do cronograma: a equipe t\xe9cnica do Uni+ deve\\ninvestigar. Se, na publica\xe7\xe3o, mesmo assim, a recusa persistir com a\\nconfigura\xe7\xe3o aparentemente correta, a equipe t\xe9cnica do Uni+ deve investigar\\na configura\xe7\xe3o gravada."],"ondeAparece":["Grava\xe7\xe3o do formul\xe1rio do processo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formulario processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);